5	use crate::generator::{Generator, utils};
6	
7	/// Generate fish completion file
8	///
9	/// Note: The fish generator currently only supports named options (-o/--option), not positional arguments.
10	#[derive(Copy, Clone, PartialEq, Eq, Debug)]
11	pub struct Fish;
12	
13	impl Generator for Fish {
14	    fn file_name(&self, name: &str) -> String {
15	        format!("{name}.fish")
16	    }
17	
18	    fn generate(&self, cmd: &Command, buf: &mut dyn Write) {
19	        self.try_generate(cmd, buf)
20	            .expect("failed to write completion file");
21	    }
22	
23	    fn try_generate(&self, cmd: &Command, buf: &mut dyn Write) -> Result<(), Error> {
24	        let bin_name = cmd
25	            .get_bin_name()
26	            .expect("crate::generate should have set the bin_name");
27	
28	        let name = escape_name(bin_name);
29	        let mut needs_fn_name = &format!("__fish_{name}_needs_command")[..];
30	        let mut using_fn_name = &format!("__fish_{name}_using_subcommand")[..];
31	        // Given `git --git-dir somedir status`, using `__fish_seen_subcommand_from` won't help us
32	        // find out `status` is the real subcommand, and not `somedir`. However, when there are no subcommands,
33	        // there is no need to use our custom stubs.
34	        if cmd.has_subcommands() {
35	            gen_subcommand_helpers(&name, cmd, buf, needs_fn_name, using_fn_name);
36	        } else {
37	            needs_fn_name = "__fish_use_subcommand";
38	            using_fn_name = "__fish_seen_subcommand_from";
39	        }
40	
41	        let generator = FishGen {
42	            root_command: bin_name,
43	            needs_fn_name,
44	            using_fn_name,
45	            helpers: String::new(),
46	            lines: String::new(),
47	        };
48	        let generator = generator.run(cmd);
49	        write!(buf, "{}{}", generator.helpers, generator.lines)
50	    }
51	}
52	
53	/// Mutable state carried through the recursive completion generation.
54	struct FishGen<'a> {
55	    root_command: &'a str,
56	    needs_fn_name: &'a str,
57	    using_fn_name: &'a str,
58	    /// Predicate functions emitted ahead of the `complete` lines.
59	    helpers: String,
60	    /// The `complete` lines.
61	    lines: String,
62	}
63	
64	impl<'a> FishGen<'a> {
65	    fn run(mut self, root: &'a Command) -> Self {
66	        // Seed the chain with the root command so its options are stripped too (e.g. a root
67	        // `--config <file>` before the subcommand path).  The root link carries option specs but
68	        // no positional name: it is not itself matched against the subcommand tokens.
69	        let root_chain = [ChainCommand {
70	            name: None,
71	            optspecs: command_optspecs(root),
72	        }];
73	        let root_value_options = command_value_option_tokens(root);
74	        self.gen_cmd(root, &[], &root_chain, &root_value_options);
75	        self
76	    }
77	
78	    /// Generate completions for `cmd` and recurse into its subcommands.
79	    ///
80	    /// `parent_commands` holds the visible subcommand names on the path to `cmd`; `chain`
81	    /// mirrors them (plus per-command argparse optspecs) and `value_options` accumulates the
82	    /// value-taking option tokens used to pad the token currently being edited.
83	    fn gen_cmd(
84	        &mut self,
85	        cmd: &Command,
86	        parent_commands: &[&str],
87	        chain: &[ChainCommand],
88	        value_options: &[String],
89	    ) {
90	        let root_command = self.root_command;
91	        let needs_fn_name = self.needs_fn_name;
92	        let using_fn_name = self.using_fn_name;
93	        debug!("gen_fish_inner");
94	        // example :
95	        //
96	        // complete
97	        //      -c {command}
98	        //      -d "{description}"
99	        //      -s {short}
100	        //      -l {long}
101	        //      -a "{possible_arguments}"
102	        //      -r # if require parameter
103	        //      -f # don't use file completion
104	        //      -n "{needs_fn_name}"            # complete for command "myprog"
105	        //      -n "{using_fn_name} subcmd1"    # complete for command "myprog subcmd1"
106	
107	        let mut basic_template = format!("complete -c {root_command}");
108	
109	        let is_deep = parent_commands.len() >= 3;
110	        if parent_commands.is_empty() {
111	            if cmd.has_subcommands() {
112	                basic_template.push_str(&format!(" -n \"{needs_fn_name}\""));
113	            }
114	        } else if !is_deep {
115	            // Shallow subcommands (one or two levels deep) use fish's stock
116	            // `__fish_seen_subcommand_from`-based predicates, preserving the historical output.
117	            let mut out = String::from(using_fn_name);
118	            match parent_commands {
119	                [] => unreachable!(),
120	                [command] => {
121	                    out.push_str(&format!(" {command}"));
122	                    if cmd.has_subcommands() {
123	                        out.push_str("; and not __fish_seen_subcommand_from");
124	                    }
125	                    let subcommands = cmd
126	                        .get_subcommands()
127	                        .flat_map(Command::get_name_and_visible_aliases);
128	                    for name in subcommands {
129	                        out.push_str(&format!(" {name}"));
130	                    }
131	                }
132	                [command, subcommand] => out.push_str(&format!(
133	                    " {command}; and __fish_seen_subcommand_from {subcommand}"
134	                )),
135	                _ => unreachable!(),
136	            }
137	            basic_template.push_str(format!(" -n \"{out}\"").as_str());
138	        } else {
139	            // Arbitrarily nested subcommands cannot be expressed with
140	            // `__fish_seen_subcommand_from` (which only looks at a single token), so each
141	            // completion references a dedicated predicate matching the *full, ordered* command
142	            // chain.  This keeps two branches that reuse identical subcommand names from
